  "python": "def pilot_policy(trace):
    action, label = trace[-1]
    name = action.name
    params = json.loads(action.arguments)
    cats = label.subset

    # Define department route aliases
    support_routes = {'local': 'slot:internal', 'partner': 'slot:customer', 'release': 'slot:public'}
    finance_routes = {'local': 'slot:internal', 'partner': 'slot:vendor', 'release': 'slot:control'}

    # Compute all destination slots for dispatch tools
    def get_destinations(agent, route, mode, receipt):
        dests = set()
        if agent == 'support':
            primary = support_routes.get(route, route)
        elif agent == 'finance':
            primary = finance_routes.get(route, route)
        else:
            primary = route
        dests.add(primary)

        if mode == 'mirror':
            dests.add('slot:public')
        elif mode == 'linked':
            if agent == 'support':
                dests.add('slot:customer')
            elif agent == 'finance':
                dests.add('slot:vendor')

        if receipt == 'external':
            dests.add('slot:audit')
        elif receipt == 'partner':
            if agent == 'support':
                partner_dest = 'slot:customer'
            else:
                partner_dest = 'slot:vendor'
            if partner_dest != primary:
                dests.add(partner_dest)
        return dests

    # Check each destination against policy
    def check_destinations(dests, cats):
        for dest in dests:
            if dest in policy:
                allowed = set(policy[dest])
                if not cats.issubset(allowed):
                    raise PolicyViolation(f'Data categories {cats} not allowed at {dest}')

    # Process tool-specific rules
    if name == 'collector/import_record':
        # Import only specific single category
        param_cat = params.get('category')
        if len(cats) != 1 or param_cat not in cats:
            raise PolicyViolation('Import must write exactly the declared category')
        # Destination slot:intake not in policy, so always allowed

    elif name == 'editor/edit':
        # No restrictions on data categories for intake→brief
        pass

    elif name == 'packer/pack':
        # No restrictions on data categories for brief/intake→bundle
        pass

    elif name in ['finance/dispatch', 'support/dispatch']:
        agent = name.split('/')[0]
        dests = get_destinations(agent, params['route'], params['mode'], params['receipt'])
        check_destinations(dests, cats)

    else:
        raise PolicyViolation(f'Unknown tool {name}')

    return None
